<?php
require_once __DIR__ . '/includes/functions.php';
require_login();$user=current_user();$id=max(0,(int)($_GET['id']??0));$st=$pdo->prepare("SELECT * FROM accommodations WHERE id=? AND status='active'");$st->execute([$id]);$item=$st->fetch();if(!$item){set_flash('Вариант проживания не найден.','danger');redirect('/catalog.php');}
$pageTitle='Бронирование — '.$item['title'];$errors=[];$from=$_POST['check_in']??($_GET['from']??'');$to=$_POST['check_out']??($_GET['to']??'');$guests=max(1,(int)($_POST['guests']??($_GET['guests']??2)));$nights=0;$total=0;
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$nights=nights_count($from,$to);$today=date('Y-m-d');
    if(!$nights)$errors[]='Дата выезда должна быть позже даты заезда.';
    if($from!==''&&$from<$today)$errors[]='Дата заезда не может быть в прошлом.';
    if($guests<1||$guests>(int)$item['capacity'])$errors[]='Количество гостей превышает вместимость выбранного варианта.';
    if(!$errors){
        try{$pdo->beginTransaction();$lock=$pdo->prepare('SELECT id FROM accommodations WHERE id=? FOR UPDATE');$lock->execute([$id]);$check=$pdo->prepare("SELECT COUNT(*) FROM bookings WHERE accommodation_id=? AND status IN ('pending','confirmed') AND check_in < ? AND check_out > ?");$check->execute([$id,$to,$from]);if((int)$check->fetchColumn()>0){$pdo->rollBack();$errors[]='На выбранные даты этот вариант уже забронирован.';}else{$total=$nights*(float)$item['price_per_night'];$insert=$pdo->prepare("INSERT INTO bookings(user_id,accommodation_id,check_in,check_out,guests,total_price,status) VALUES(?,?,?,?,?,?,'pending')");$insert->execute([$user['id'],$id,$from,$to,$guests,$total]);$pdo->commit();set_flash('Заявка отправлена. Администратор подтвердит бронирование.');redirect('/profile.php');}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]='Не удалось сохранить заявку. Попробуйте ещё раз.';}
    }
}
if($nights>0)$total=$nights*(float)$item['price_per_night'];
include __DIR__.'/includes/header.php';
?>
<section class="container booking-page"><div class="booking-heading"><span class="eyebrow">ЗАЯВКА НА ПРОЖИВАНИЕ</span><h1>Оформление бронирования</h1><p>Выберите даты и количество гостей. Стоимость рассчитается автоматически.</p></div><div class="booking-layout"><article class="booking-stay"><div class="booking-visual visual-<?= (int)$item['id']%3 ?>"><span class="room-art">⌂</span></div><div class="booking-stay-info"><span class="eyebrow"><?= e($item['type']) ?></span><h2><?= e($item['title']) ?></h2><p>До <?= (int)$item['capacity'] ?> гостей</p><strong><?= number_format((float)$item['price_per_night'],0,',',' ') ?> ₽ <small>/ ночь</small></strong></div></article><div class="booking-form-card"><h2>Ваши даты</h2><?php if($errors): ?><div class="alert alert-danger"><?php foreach($errors as $error): ?><div><?= e($error) ?></div><?php endforeach; ?></div><?php endif; ?><form method="post" id="booking-form" data-price="<?= e($item['price_per_night']) ?>"><?= csrf_field() ?><div class="row g-3"><div class="col-md-6"><label class="form-label">Дата заезда</label><input class="form-control" type="date" id="check_in" name="check_in" min="<?= e(date('Y-m-d')) ?>" required value="<?= e($from) ?>"></div><div class="col-md-6"><label class="form-label">Дата выезда</label><input class="form-control" type="date" id="check_out" name="check_out" min="<?= e(date('Y-m-d',strtotime('+1 day'))) ?>" required value="<?= e($to) ?>"></div><div class="col-12"><label class="form-label">Количество гостей</label><select class="form-select" name="guests"><?php for($i=1;$i<=(int)$item['capacity'];$i++): ?><option value="<?= $i ?>" <?= $guests===$i?'selected':'' ?>><?= $i ?></option><?php endfor; ?></select></div></div><div class="price-summary"><div><span>Количество ночей</span><strong id="nights-value"><?= $nights ?: '—' ?></strong></div><div><span>Стоимость за ночь</span><strong><?= number_format((float)$item['price_per_night'],0,',',' ') ?> ₽</strong></div><div class="price-total"><span>Итого</span><strong id="total-value"><?= number_format($total,0,',',' ') ?> ₽</strong></div></div><button class="btn btn-green w-100 btn-lg">Отправить заявку</button><p class="muted-note">После отправки заявка получит статус «Ожидает подтверждения».</p></form></div></div></section>
<?php include __DIR__.'/includes/footer.php'; ?>
